<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const emit=defineEmits(['imported']),cap=ref(null),manifest=ref(null),files=ref(new Map()),preview=ref(null),result=ref(null),busy=ref(false),message=ref(''),progress=ref(''),controller=new AbortController()
const sha=async value=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',value))].map(value=>value.toString(16).padStart(2,'0')).join('')
const json=async(method,path,data)=>request({method,url:'/muse/migration/jubian'+path,data,signal:controller.signal})
let revision=0,operation=null
onMounted(async()=>{try{cap.value=await json('get','/capabilities')}catch(error){if(!controller.signal.aborted)message.value=error.message}})
onBeforeUnmount(()=>{revision++;controller.abort()})
async function choose(event){const current=++revision;manifest.value=null;preview.value=null;result.value=null;operation=null;message.value='';const selected=new Map([...event.target.files].map(file=>[file.name,file]));files.value=selected;try{const candidates=[];for(const file of selected.values()){if(file.size>cap.value.max_manifest_bytes||/-media-[a-f0-9]{64}\.json$/.test(file.name)||/-source\.json$/.test(file.name))continue;const parsed=JSON.parse(await file.text());if(parsed.schema==='muse-jubian-exchange-v1')candidates.push(parsed)}if(candidates.length!==1)throw Error('请一次选择一个完整导出的项目清单及其媒体 JSON 文件');const selectedManifest=candidates[0];for(const item of selectedManifest.media){if(!selected.has(item.export_file))throw Error('缺少原媒体文件：'+item.export_file)}const checked=await json('post','/preview',{manifest:selectedManifest});if(current!==revision)return;manifest.value=selectedManifest;preview.value=checked;const identity=await sha(new TextEncoder().encode(JSON.stringify(selectedManifest)));const cacheKey='muse-jubian-import:'+cap.value.database_id+':'+identity;operation=localStorage.getItem(cacheKey)||crypto.randomUUID();localStorage.setItem(cacheKey,operation)}catch(error){if(current===revision&&!controller.signal.aborted)message.value=error.message}}
async function run(){if(!manifest.value||!cap.value||!operation||busy.value)return;const original=manifest.value,database=cap.value.database_id,current=revision;try{await ElMessageBox.confirm('将创建一个新的 LocalMiniDrama 项目，保留剧变源和已有本地项目。实际媒体按分块校验后导入；源审核、授权和模型配置不会转成新项目批准。','确认导入项目副本',{confirmButtonText:'导入新项目',cancelButtonText:'取消'})}catch(cancelled){return}if(current!==revision||controller.signal.aborted)return;busy.value=true;message.value='';try{await json('post','/reserve',{database_id:database,operation_id:operation,manifest:original});for(const descriptor of original.media){const file=files.value.get(descriptor.export_file);if(!file||file.size>Math.ceil(cap.value.max_media_bytes*4/3)+4096)throw Error('原媒体文件缺失或超过本次部署限额');const sidecar=JSON.parse(await file.text());const binary=atob(sidecar.data_base64),bytes=Uint8Array.from(binary,character=>character.charCodeAt(0));if(sidecar.sha256!==descriptor.sha256||bytes.length!==descriptor.bytes||await sha(bytes)!==descriptor.sha256)throw Error('原媒体 SHA 或长度改变，已停止导入');const count=Math.ceil(bytes.length/cap.value.chunk_bytes);for(let index=0;index<count;index++){if(controller.signal.aborted)throw Error('已停止等待，保留原操作与已接收分块');const chunk=bytes.slice(index*cap.value.chunk_bytes,(index+1)*cap.value.chunk_bytes);let base64='';for(let offset=0;offset<chunk.length;offset+=32768)base64+=String.fromCharCode(...chunk.subarray(offset,offset+32768));progress.value=`媒体 ${descriptor.export_file} · 分块 ${index+1}/${count}`;await json('post','/chunks',{database_id:database,operation_id:operation,source_url_sha256:descriptor.source_url_sha256,sha256:descriptor.sha256,kind:descriptor.kind,media_type:descriptor.media_type,total_bytes:bytes.length,total_chunks:count,index,chunk_sha256:await sha(chunk),data_base64:btoa(base64)})}}progress.value='正在提交完整映射';const saved=await json('post','/import',{database_id:database,operation_id:operation,manifest:original});if(current!==revision)return;result.value=saved;progress.value='';emit('imported');ElMessage.success('已创建独立项目副本，源项目保持原状')}catch(error){if(!controller.signal.aborted)message.value=error.message+'；重新选择同一导出文件后继续会复用原操作与已完成分块。'}finally{busy.value=false}}
</script>
<template>
  <section class="muse-migration">
    <p>先在明确启用的剧变迁移配置中运行 <code>jubian_project_export</code>，再选择它保存的清单和媒体 JSON 文件。本入口不登录剧变、不下载清单里的远端地址、不调用生成 API。</p>
    <el-alert v-if="message" :title="message" type="error" :closable="false" show-icon />
    <label>选择同一个导出包的全部 JSON 文件 <input type="file" accept=".json,application/json" multiple :disabled="!cap||busy" @change="choose" /></label>
    <div v-if="preview"><p>源项目 {{preview.source_project_id}} · {{preview.counts.episodes}} 集 · {{preview.counts.assets}} 项资产 · {{preview.counts.storyboards}} 个制作包 · {{preview.counts.media}} 份媒体</p><p>原数字 ID 只保存在来源映射中，新项目重新分配原生 ID。缺少明确采用或排序信息会报告问题，不按最新历史猜选。</p><el-button type="primary" :loading="busy" :disabled="busy||!manifest" @click="run">导入为新项目</el-button></div>
    <p v-if="progress" role="status">{{progress}}</p>
    <div v-if="result"><p>新项目 ID：{{result.project_id}}；操作：{{result.operation_id}}</p><p>原模型配置和质量批准未转移。请在项目列表打开副本，核对映射、采用版本、台词及素材，再选择已配置的模型。</p><details><summary>来源与原生 ID 映射</summary><pre>{{JSON.stringify(result,null,2)}}</pre></details></div>
  </section>
</template>
<style scoped>
.muse-migration{display:grid;gap:14px;min-width:0;color:var(--el-text-color-primary)}.muse-migration p{margin:0;line-height:1.6;overflow-wrap:anywhere}.muse-migration label{display:grid;gap:8px}.muse-migration input{max-width:100%;font:inherit;font-size:16px}.muse-migration pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:40vh;overflow:auto;background:var(--el-fill-color-light);padding:12px}
</style>
